mapper.select:
SELECT om.order_id AS orderId, om.order_no AS orderNo, om.guest_name AS guestName, om.guest_mobile AS guestMobile, COALESCE(ca.channel_name, om.source_label_snapshot, '') AS channelName, om.status AS orderStatus, COALESCE(rc.display_name, rc.name, om.room_category_name_snapshot, '') AS roomCategoryName, COALESCE(r.room_name, om.room_name_snapshot, '') AS roomName, om.start_at AS startAt, om.end_at AS endAt, om.created_at AS createdAt, COALESCE(om.total_pay_price_cent, om.total_price_cent, 0) AS totalPayPriceCent, COALESCE(om.remark, '') AS remark, COALESCE(( SELECT pm.name FROM pms_member pm WHERE pm.camp_id = om.camp_id AND pm.is_deleted = 0 AND pm.wecom_user_id IS NOT NULL AND pm.wecom_user_id != '' ORDER BY pm.updated_at DESC, pm.member_id ASC LIMIT 1 ), '未分配') AS assignee FROM order_main om LEFT JOIN channel_account ca ON ca.account_id = om.channel_id AND ca.camp_id = om.camp_id LEFT JOIN room_category rc ON rc.room_category_id = om.room_category_id AND rc.camp_id = om.camp_id AND rc.is_deleted = 0 LEFT JOIN room r ON r.room_id = om.room_id AND r.camp_id = om.camp_id AND r.is_deleted = 0 WHERE om.camp_id = #{campId} AND om.is_deleted = 0 AND om.source_type = 'wechat_service'
AND om.poi_id = #{poiId}
AND om.created_at >= #{rangeStart}
AND om.created_at < #{rangeEndExclusive}
ORDER BY om.created_at DESC, om.order_id DESC

SELECT CAST(r.room_id AS CHAR) AS id, CONCAT(COALESCE(rc.display_name, rc.name), ' / ', r.room_name) AS roomName, CASE WHEN r.sale_type = 'available' OR r.status = 1 THEN '今夜可售' ELSE '不可售' END AS status, CASE WHEN r.sale_type = 'available' OR r.status = 1 THEN 1 ELSE 0 END AS availableTonight, CASE WHEN r.sale_type = 'available' OR r.status = 1 THEN '锁定房源' ELSE '查看房态' END AS action FROM room r JOIN room_category rc ON rc.room_category_id = r.room_category_id AND rc.camp_id = r.camp_id AND rc.is_deleted = 0 WHERE r.camp_id = #{campId} AND r.is_deleted = 0
AND r.poi_id = #{poiId}
ORDER BY r.sort_no ASC, r.room_id ASC LIMIT 6
